//! A reader and writer for the JSON documents this crate handles: the update
//! feed, the pending-install record, and a crash report.
//!
//! Not a JSON library. It has no derive machinery, it keeps object members in
//! the order they were written, and its writer is one [`fmt::Display`] impl. The
//! reason it exists at all is the reason the crate has no dependencies: the
//! updater is the component that cannot be repaired by an update, so its whole
//! decision path should be readable in one sitting.
//!
//! Reading is what the feed needs; writing is what [`crate::pending`] and
//! [`crate::crash`] need, and both write documents this same parser must be able
//! to read back — which is a property the tests check directly rather than by
//! inspection.
//!
//! It is nonetheless a *strict* reader — trailing commas, unquoted keys, single
//! quotes and `NaN` are all errors. A feed is generated by a script we own; a
//! reader that forgives sloppiness is a reader that hides the day the script
//! started emitting something slightly wrong.
//!
//! ```
//! use silka_dist::json::Json;
//!
//! let value = Json::parse(r#"{ "app": "dev.silka.dashboard", "releases": [] }"#).unwrap();
//! assert_eq!(value.get("app").and_then(Json::as_str), Some("dev.silka.dashboard"));
//! assert_eq!(value.get("releases").and_then(Json::as_array).map(|items| items.len()), Some(0));
//! ```

use std::fmt;

/// A parsed JSON value.
///
/// Objects are a `Vec` of pairs rather than a map: a feed has a handful of keys,
/// a linear scan is faster than hashing them, and the original order survives —
/// which matters when a human is asked to compare a feed against its generator.
#[derive(Debug, Clone, PartialEq)]
pub enum Json {
    /// `null`
    Null,
    /// `true` / `false`
    Bool(bool),
    /// Any JSON number, held as `f64` exactly as the specification's own
    /// interchange advice suggests. [`Json::as_u64`] is the guarded way back to
    /// an integer.
    Number(f64),
    /// A string, with escapes already resolved.
    String(String),
    /// An array.
    Array(Vec<Json>),
    /// An object, in document order.
    Object(Vec<(String, Json)>),
}

impl Json {
    /// Parse a whole document. Trailing content after the top-level value is an
    /// error, because it is nearly always a second document glued on by mistake.
    pub fn parse(text: &str) -> Result<Json, JsonError> {
        let mut parser = Parser {
            bytes: text.as_bytes(),
            position: 0,
        };
        parser.skip_whitespace();
        let value = parser.value(0)?;
        parser.skip_whitespace();
        if parser.position != parser.bytes.len() {
            return Err(parser.error("trailing content after the top-level value"));
        }
        Ok(value)
    }

    /// Look up a member of an object. `None` for every other kind of value, so a
    /// chain of `get` on the wrong shape ends in `None` rather than a panic.
    pub fn get(&self, key: &str) -> Option<&Json> {
        match self {
            Json::Object(members) => members
                .iter()
                .find(|(name, _)| name == key)
                .map(|(_, value)| value),
            _ => None,
        }
    }

    /// The string, if this is one.
    pub fn as_str(&self) -> Option<&str> {
        match self {
            Json::String(text) => Some(text.as_str()),
            _ => None,
        }
    }

    /// The number, if this is one.
    pub fn as_f64(&self) -> Option<f64> {
        match self {
            Json::Number(value) => Some(*value),
            _ => None,
        }
    }

    /// The number as a `u64`, if it is one exactly.
    ///
    /// A file size of `4.5` or `-1` is not a smaller file, it is a broken feed,
    /// so both come back as `None` instead of being rounded into plausibility.
    pub fn as_u64(&self) -> Option<u64> {
        let value = self.as_f64()?;
        if !value.is_finite() || value < 0.0 || value.fract() != 0.0 {
            return None;
        }
        // 2^53 is where f64 stops being able to tell consecutive integers apart.
        if value > 9_007_199_254_740_992.0 {
            return None;
        }
        Some(value as u64)
    }

    /// The boolean, if this is one.
    pub fn as_bool(&self) -> Option<bool> {
        match self {
            Json::Bool(value) => Some(*value),
            _ => None,
        }
    }

    /// The elements, if this is an array.
    pub fn as_array(&self) -> Option<&[Json]> {
        match self {
            Json::Array(items) => Some(items.as_slice()),
            _ => None,
        }
    }

    /// Whether this is `null`.
    ///
    /// A feed writes `null` where a value is deliberately absent, and the callers
    /// in [`crate::feed`] treat it exactly like a missing key.
    pub fn is_null(&self) -> bool {
        matches!(self, Json::Null)
    }

    /// The name of this kind of value, for error messages.
    pub fn kind(&self) -> &'static str {
        match self {
            Json::Null => "null",
            Json::Bool(_) => "boolean",
            Json::Number(_) => "number",
            Json::String(_) => "string",
            Json::Array(_) => "array",
            Json::Object(_) => "object",
        }
    }

    /// Build a string value without spelling out the variant.
    pub fn string(text: impl Into<String>) -> Json {
        Json::String(text.into())
    }

    /// Build a number from an integer, which is every number this crate writes.
    pub fn number(value: u64) -> Json {
        Json::Number(value as f64)
    }

    /// Build an object from pairs.
    ///
    /// Takes an iterator rather than a map so that the caller's order is the
    /// document's order: a record written the same way twice diffs cleanly.
    pub fn object<K: Into<String>>(members: impl IntoIterator<Item = (K, Json)>) -> Json {
        Json::Object(
            members
                .into_iter()
                .map(|(key, value)| (key.into(), value))
                .collect(),
        )
    }
}

// ---------------------------------------------------------------------------
// Writing
// ---------------------------------------------------------------------------

/// Compact JSON — no indentation, no trailing newline.
///
/// Every document this crate writes is machine-written and machine-read, and the
/// one thing that matters is that it comes back through [`Json::parse`]
/// unchanged. Two rules make that true:
///
/// - **Integers print without a fractional part.** `4.0` would read back as the
///   same number, but a size field spelled `41234567.0` is a field that makes a
///   human wonder, and wondering costs more than the branch.
/// - **A non-finite number prints as `null`.** `NaN` and `inf` are not JSON at
///   all, and a writer that emits them produces a file its own reader rejects —
///   which, for a crash report, means losing the report *and* the reason.
impl fmt::Display for Json {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Json::Null => f.write_str("null"),
            Json::Bool(true) => f.write_str("true"),
            Json::Bool(false) => f.write_str("false"),
            Json::Number(value) => {
                if !value.is_finite() {
                    return f.write_str("null");
                }
                if value.fract() == 0.0 && value.abs() < 9_007_199_254_740_992.0 {
                    write!(f, "{}", *value as i64)
                } else {
                    write!(f, "{value}")
                }
            }
            Json::String(text) => write_string(f, text),
            Json::Array(items) => {
                f.write_str("[")?;
                for (index, item) in items.iter().enumerate() {
                    if index > 0 {
                        f.write_str(",")?;
                    }
                    write!(f, "{item}")?;
                }
                f.write_str("]")
            }
            Json::Object(members) => {
                f.write_str("{")?;
                for (index, (key, value)) in members.iter().enumerate() {
                    if index > 0 {
                        f.write_str(",")?;
                    }
                    write_string(f, key)?;
                    f.write_str(":")?;
                    write!(f, "{value}")?;
                }
                f.write_str("}")
            }
        }
    }
}

/// Write one quoted, escaped JSON string.
///
/// Every control character below `0x20` becomes a `\u00XX` escape rather than
/// being passed through, which is the writing half of the rule the parser
/// enforces when reading: a panic message with a raw newline in it must not be
/// able to reshape the document it lands in.
fn write_string(f: &mut fmt::Formatter<'_>, text: &str) -> fmt::Result {
    f.write_str("\"")?;
    for character in text.chars() {
        match character {
            '"' => f.write_str("\\\"")?,
            '\\' => f.write_str("\\\\")?,
            '\n' => f.write_str("\\n")?,
            '\r' => f.write_str("\\r")?,
            '\t' => f.write_str("\\t")?,
            '\u{08}' => f.write_str("\\b")?,
            '\u{0c}' => f.write_str("\\f")?,
            control if (control as u32) < 0x20 => write!(f, "\\u{:04x}", control as u32)?,
            other => write!(f, "{other}")?,
        }
    }
    f.write_str("\"")
}

// ---------------------------------------------------------------------------
// Parser
// ---------------------------------------------------------------------------

/// How deep a document may nest.
///
/// A feed is three levels deep. The limit is here because a recursive-descent
/// parser fed `[[[[[…` blows the stack, and a stack overflow in the updater is a
/// crash on startup that no crash reporter survives to describe.
const MAX_DEPTH: usize = 32;

struct Parser<'a> {
    bytes: &'a [u8],
    position: usize,
}

impl<'a> Parser<'a> {
    fn error(&self, message: &str) -> JsonError {
        JsonError {
            message: message.to_string(),
            offset: self.position,
        }
    }

    fn peek(&self) -> Option<u8> {
        self.bytes.get(self.position).copied()
    }

    fn skip_whitespace(&mut self) {
        while let Some(byte) = self.peek() {
            match byte {
                b' ' | b'\t' | b'\n' | b'\r' => self.position += 1,
                _ => break,
            }
        }
    }

    fn expect(&mut self, byte: u8, what: &str) -> Result<(), JsonError> {
        if self.peek() == Some(byte) {
            self.position += 1;
            Ok(())
        } else {
            Err(self.error(what))
        }
    }

    fn literal(&mut self, word: &str) -> Result<(), JsonError> {
        let end = self.position + word.len();
        if end <= self.bytes.len() && &self.bytes[self.position..end] == word.as_bytes() {
            self.position = end;
            Ok(())
        } else {
            Err(self.error("unknown literal"))
        }
    }

    fn value(&mut self, depth: usize) -> Result<Json, JsonError> {
        if depth > MAX_DEPTH {
            return Err(self.error("nested too deeply"));
        }
        match self.peek() {
            None => Err(self.error("expected a value, found the end of the document")),
            Some(b'{') => self.object(depth),
            Some(b'[') => self.array(depth),
            Some(b'"') => Ok(Json::String(self.string()?)),
            Some(b't') => {
                self.literal("true")?;
                Ok(Json::Bool(true))
            }
            Some(b'f') => {
                self.literal("false")?;
                Ok(Json::Bool(false))
            }
            Some(b'n') => {
                self.literal("null")?;
                Ok(Json::Null)
            }
            Some(_) => self.number(),
        }
    }

    fn object(&mut self, depth: usize) -> Result<Json, JsonError> {
        self.expect(b'{', "expected `{`")?;
        let mut members: Vec<(String, Json)> = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(b'}') {
            self.position += 1;
            return Ok(Json::Object(members));
        }
        loop {
            self.skip_whitespace();
            let key = self.string()?;
            self.skip_whitespace();
            self.expect(b':', "expected `:` after an object key")?;
            self.skip_whitespace();
            let value = self.value(depth + 1)?;
            members.push((key, value));
            self.skip_whitespace();
            match self.peek() {
                Some(b',') => {
                    self.position += 1;
                }
                Some(b'}') => {
                    self.position += 1;
                    return Ok(Json::Object(members));
                }
                _ => return Err(self.error("expected `,` or `}` in an object")),
            }
        }
    }

    fn array(&mut self, depth: usize) -> Result<Json, JsonError> {
        self.expect(b'[', "expected `[`")?;
        let mut items: Vec<Json> = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(b']') {
            self.position += 1;
            return Ok(Json::Array(items));
        }
        loop {
            self.skip_whitespace();
            let value = self.value(depth + 1)?;
            items.push(value);
            self.skip_whitespace();
            match self.peek() {
                Some(b',') => {
                    self.position += 1;
                }
                Some(b']') => {
                    self.position += 1;
                    return Ok(Json::Array(items));
                }
                _ => return Err(self.error("expected `,` or `]` in an array")),
            }
        }
    }

    fn string(&mut self) -> Result<String, JsonError> {
        self.expect(b'"', "expected a string")?;
        let mut out: Vec<u8> = Vec::new();
        loop {
            let byte = match self.peek() {
                Some(byte) => byte,
                None => return Err(self.error("string was never closed")),
            };
            self.position += 1;
            match byte {
                b'"' => break,
                b'\\' => {
                    let escape = match self.peek() {
                        Some(escape) => escape,
                        None => return Err(self.error("escape at the end of the document")),
                    };
                    self.position += 1;
                    match escape {
                        b'"' => out.push(b'"'),
                        b'\\' => out.push(b'\\'),
                        b'/' => out.push(b'/'),
                        b'b' => out.push(0x08),
                        b'f' => out.push(0x0c),
                        b'n' => out.push(b'\n'),
                        b'r' => out.push(b'\r'),
                        b't' => out.push(b'\t'),
                        b'u' => {
                            let code = self.unicode_escape()?;
                            let mut buffer = [0u8; 4];
                            out.extend_from_slice(code.encode_utf8(&mut buffer).as_bytes());
                        }
                        _ => return Err(self.error("unknown escape sequence")),
                    }
                }
                // Raw control characters are invalid JSON, and letting them
                // through means a feed can smuggle a newline into a version
                // string that later gets written to a log verbatim.
                0x00..=0x1f => return Err(self.error("raw control character in a string")),
                _ => out.push(byte),
            }
        }
        String::from_utf8(out).map_err(|_| self.error("string is not valid UTF-8"))
    }

    /// A `\uXXXX` escape, including the surrogate pair that spells an emoji.
    fn unicode_escape(&mut self) -> Result<char, JsonError> {
        let first = self.hex4()?;
        // Low surrogate on its own: nothing valid can start with one.
        if (0xdc00..=0xdfff).contains(&first) {
            return Err(self.error("unpaired low surrogate"));
        }
        if !(0xd800..=0xdbff).contains(&first) {
            return match char::from_u32(first) {
                Some(value) => Ok(value),
                None => Err(self.error("escape is not a character")),
            };
        }
        // High surrogate: a `\uXXXX` low surrogate must follow immediately.
        self.expect(b'\\', "expected a low surrogate after a high surrogate")?;
        self.expect(b'u', "expected a low surrogate after a high surrogate")?;
        let second = self.hex4()?;
        if !(0xdc00..=0xdfff).contains(&second) {
            return Err(self.error("high surrogate was not followed by a low surrogate"));
        }
        let combined = 0x10000 + ((first - 0xd800) << 10) + (second - 0xdc00);
        match char::from_u32(combined) {
            Some(value) => Ok(value),
            None => Err(self.error("surrogate pair is not a character")),
        }
    }

    fn hex4(&mut self) -> Result<u32, JsonError> {
        let end = self.position + 4;
        if end > self.bytes.len() {
            return Err(self.error("truncated `\\u` escape"));
        }
        let mut value = 0u32;
        for index in self.position..end {
            let digit = match self.bytes[index] {
                byte @ b'0'..=b'9' => u32::from(byte - b'0'),
                byte @ b'a'..=b'f' => u32::from(byte - b'a' + 10),
                byte @ b'A'..=b'F' => u32::from(byte - b'A' + 10),
                _ => return Err(self.error("`\\u` escape is not four hex digits")),
            };
            value = value * 16 + digit;
        }
        self.position = end;
        Ok(value)
    }

    fn number(&mut self) -> Result<Json, JsonError> {
        let start = self.position;
        if self.peek() == Some(b'-') {
            self.position += 1;
        }
        let integer_start = self.position;
        while matches!(self.peek(), Some(b'0'..=b'9')) {
            self.position += 1;
        }
        if self.position == integer_start {
            return Err(self.error("expected a value"));
        }
        // `01` is not one, and a feed that emits it is a feed whose generator
        // zero-padded a field somewhere. Better to fail than to guess.
        if self.position - integer_start > 1 && self.bytes[integer_start] == b'0' {
            return Err(self.error("number has a leading zero"));
        }
        if self.peek() == Some(b'.') {
            self.position += 1;
            let fraction_start = self.position;
            while matches!(self.peek(), Some(b'0'..=b'9')) {
                self.position += 1;
            }
            if self.position == fraction_start {
                return Err(self.error("number has a `.` with no digits after it"));
            }
        }
        if matches!(self.peek(), Some(b'e') | Some(b'E')) {
            self.position += 1;
            if matches!(self.peek(), Some(b'+') | Some(b'-')) {
                self.position += 1;
            }
            let exponent_start = self.position;
            while matches!(self.peek(), Some(b'0'..=b'9')) {
                self.position += 1;
            }
            if self.position == exponent_start {
                return Err(self.error("number has an exponent with no digits"));
            }
        }
        let text = match std::str::from_utf8(&self.bytes[start..self.position]) {
            Ok(text) => text,
            Err(_) => return Err(self.error("number is not valid UTF-8")),
        };
        match text.parse::<f64>() {
            Ok(value) => Ok(Json::Number(value)),
            Err(_) => Err(self.error("number is out of range")),
        }
    }
}

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

/// Where the document stopped making sense, and why.
///
/// The byte offset is carried because a feed is machine-written: nobody is going
/// to eyeball 40 KB of JSON, they are going to jump to the offset.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct JsonError {
    message: String,
    offset: usize,
}

impl JsonError {
    /// What went wrong.
    pub fn message(&self) -> &str {
        &self.message
    }

    /// The byte offset into the document.
    pub fn offset(&self) -> usize {
        self.offset
    }
}

impl fmt::Display for JsonError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{} (at byte {})", self.message, self.offset)
    }
}

impl std::error::Error for JsonError {}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn nilai_dasar() {
        assert_eq!(Json::parse("null").unwrap(), Json::Null);
        assert_eq!(Json::parse("true").unwrap(), Json::Bool(true));
        assert_eq!(Json::parse("false").unwrap(), Json::Bool(false));
        assert_eq!(Json::parse("  17 ").unwrap(), Json::Number(17.0));
        assert_eq!(
            Json::parse("\"halo\"").unwrap(),
            Json::String("halo".to_string())
        );
    }

    #[test]
    fn objek_menjaga_urutan() {
        let value = Json::parse(r#"{"b":1,"a":2}"#).unwrap();
        match value {
            Json::Object(members) => {
                assert_eq!(members[0].0, "b");
                assert_eq!(members[1].0, "a");
            }
            other => panic!("harus objek, dapat {}", other.kind()),
        }
    }

    #[test]
    fn wadah_kosong() {
        assert_eq!(Json::parse("{}").unwrap(), Json::Object(Vec::new()));
        assert_eq!(Json::parse("[]").unwrap(), Json::Array(Vec::new()));
        assert_eq!(Json::parse("[ ]").unwrap(), Json::Array(Vec::new()));
    }

    #[test]
    fn bersarang() {
        let text = r#"{ "a": [1, {"b": [true, null]}] }"#;
        let value = Json::parse(text).unwrap();
        let inner = value.get("a").unwrap().as_array().unwrap();
        assert_eq!(inner.len(), 2);
        let nested = inner[1].get("b").unwrap().as_array().unwrap();
        assert_eq!(nested[0], Json::Bool(true));
        assert!(nested[1].is_null());
    }

    #[test]
    fn get_pada_bentuk_salah_mengembalikan_none() {
        let value = Json::parse("[1,2]").unwrap();
        assert!(value.get("apa pun").is_none());
        assert!(value.as_str().is_none());
        assert!(Json::parse("3").unwrap().as_array().is_none());
        assert!(Json::parse("3").unwrap().as_bool().is_none());
    }

    #[test]
    fn angka() {
        assert_eq!(Json::parse("-0.5").unwrap().as_f64(), Some(-0.5));
        assert_eq!(Json::parse("1e3").unwrap().as_f64(), Some(1000.0));
        assert_eq!(Json::parse("1E+3").unwrap().as_f64(), Some(1000.0));
        assert_eq!(Json::parse("1e-3").unwrap().as_f64(), Some(0.001));
        assert_eq!(Json::parse("41234567").unwrap().as_u64(), Some(41_234_567));
    }

    #[test]
    fn as_u64_menolak_yang_bukan_bilangan_bulat_positif() {
        assert_eq!(Json::parse("4.5").unwrap().as_u64(), None);
        assert_eq!(Json::parse("-1").unwrap().as_u64(), None);
        assert_eq!(Json::parse("1e300").unwrap().as_u64(), None);
        assert_eq!(Json::parse("\"7\"").unwrap().as_u64(), None);
    }

    #[test]
    fn escape_string() {
        let value = Json::parse(r#""a\"b\\c\/d\ne\tf""#).unwrap();
        assert_eq!(value.as_str(), Some("a\"b\\c/d\ne\tf"));
    }

    #[test]
    fn escape_unicode_dan_pasangan_pengganti() {
        assert_eq!(Json::parse(r#""\u00e9""#).unwrap().as_str(), Some("\u{e9}"));
        // U+1F600, spelled as a surrogate pair the way JSON requires.
        assert_eq!(
            Json::parse(r#""\ud83d\ude00""#).unwrap().as_str(),
            Some("\u{1f600}")
        );
    }

    #[test]
    fn utf8_mentah_lolos_apa_adanya() {
        assert_eq!(
            Json::parse("\"café ☕\"").unwrap().as_str(),
            Some("café ☕")
        );
    }

    #[test]
    fn bentuk_yang_ditolak() {
        for text in [
            "",
            "{",
            "[1,]",
            "{\"a\":1,}",
            "{a:1}",
            "'a'",
            "{\"a\" 1}",
            "1 2",
            "tru",
            "NaN",
            "01",
            "\"belum ditutup",
            "\"\\q\"",
            "\"\\ud83d\"",
            "\"\\udc00\"",
            "\"\\u00\"",
            "1.",
            "1e",
        ] {
            assert!(
                Json::parse(text).is_err(),
                "{text:?} seharusnya ditolak, bukan diterima"
            );
        }
    }

    #[test]
    fn karakter_kendali_mentah_ditolak() {
        assert!(Json::parse("\"a\nb\"").is_err());
    }

    #[test]
    fn sarang_terlalu_dalam_ditolak_bukan_bikin_stack_overflow() {
        let text = "[".repeat(200);
        let error = Json::parse(&text).expect_err("harus ditolak");
        assert!(error.message().contains("deep"), "{}", error.message());
    }

    #[test]
    fn galat_menyebut_offset() {
        let error = Json::parse("{\"a\": }").expect_err("harus ditolak");
        assert!(error.offset() > 0);
        assert!(error.to_string().contains("at byte"));
    }

    // -- writing -----------------------------------------------------------

    #[test]
    fn menulis_nilai_dasar() {
        assert_eq!(Json::Null.to_string(), "null");
        assert_eq!(Json::Bool(true).to_string(), "true");
        assert_eq!(Json::number(41_234_567).to_string(), "41234567");
        assert_eq!(Json::Number(0.5).to_string(), "0.5");
        assert_eq!(Json::string("halo").to_string(), "\"halo\"");
    }

    #[test]
    fn bilangan_bulat_ditulis_tanpa_pecahan() {
        assert_eq!(Json::Number(4.0).to_string(), "4");
        assert_eq!(Json::Number(-7.0).to_string(), "-7");
    }

    #[test]
    fn angka_tak_hingga_jadi_null_bukan_dokumen_rusak() {
        assert_eq!(Json::Number(f64::NAN).to_string(), "null");
        assert_eq!(Json::Number(f64::INFINITY).to_string(), "null");
        // The point of the rule: what we wrote still reads back.
        assert!(Json::parse(&Json::Number(f64::NAN).to_string()).is_ok());
    }

    #[test]
    fn menulis_objek_dan_larik_dalam_urutan_penulisan() {
        let value = Json::object([
            ("b", Json::number(1)),
            ("a", Json::Array(vec![Json::Bool(false), Json::Null])),
        ]);
        assert_eq!(value.to_string(), r#"{"b":1,"a":[false,null]}"#);
    }

    #[test]
    fn escape_saat_menulis() {
        let value = Json::string("baris\nsatu\t\"dua\"\\tiga");
        assert_eq!(value.to_string(), r#""baris\nsatu\t\"dua\"\\tiga""#);
    }

    #[test]
    fn karakter_kendali_lain_jadi_escape_u() {
        assert_eq!(Json::string("\u{1}").to_string(), "\"\\u0001\"");
        assert_eq!(Json::string("\u{1f}").to_string(), "\"\\u001f\"");
        assert_eq!(Json::string("\r").to_string(), "\"\\r\"");
        assert_eq!(Json::string("\u{08}\u{0c}").to_string(), r#""\b\f""#);
    }

    #[test]
    fn utf8_ditulis_apa_adanya() {
        assert_eq!(Json::string("café ☕ 🙂").to_string(), "\"café ☕ 🙂\"");
    }

    #[test]
    fn tulis_lalu_baca_kembali_menghasilkan_nilai_yang_sama() {
        let value = Json::object([
            ("app", Json::string("dev.silka.dashboard")),
            ("size", Json::number(41_234_567)),
            ("ratio", Json::Number(0.25)),
            ("mandatory", Json::Bool(true)),
            ("notes", Json::Null),
            (
                "message",
                Json::string("panic di baris\nkedua: \"berkas hilang\""),
            ),
            (
                "versions",
                Json::Array(vec![Json::string("1.3.0"), Json::string("1.4.0")]),
            ),
        ]);
        let text = value.to_string();
        assert_eq!(Json::parse(&text).expect("harus terbaca kembali"), value);
    }

    #[test]
    fn pesan_panik_tidak_bisa_membentuk_ulang_dokumen() {
        // The attack this guards: a panic message containing a quote and a
        // brace would otherwise close the record and open a new field.
        let hostile = "\", \"app\": \"dev.evil.app";
        let value = Json::object([("message", Json::string(hostile))]);
        let parsed = Json::parse(&value.to_string()).unwrap();
        assert_eq!(parsed.get("message").and_then(Json::as_str), Some(hostile));
        assert!(parsed.get("app").is_none());
    }
}
